1	import { execFile } from 'node:child_process';
2	import { mkdir, mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
3	import { tmpdir } from 'node:os';
4	import { basename, dirname, join, relative, resolve } from 'node:path';
5	import { fileURLToPath } from 'node:url';
6	import { promisify } from 'node:util';
7	import { afterEach, expect, it } from 'vitest';
8	
9	const execute = promisify(execFile);
10	const runCase = fileURLToPath(new URL('./fixtures/sdk-schema-case.mjs', import.meta.url));
11	const roots: string[] = [];
12	const schema = {
13	  type: 'object',
14	  properties: { ok: { type: 'boolean' } },
15	  required: ['ok'],
16	  additionalProperties: false,
17	};
18	const modes = ['success', 'error', 'abort'] as const;
19	type Mode = (typeof modes)[number];
20	interface State {
21	  actualTemp: string;
22	  entriesBefore: string[];
23	  entriesAfter: string[];
24	  outcome: {
25	    kind: 'resolved' | 'rejected';
26	    finalResponse?: string;
27	    name?: string;
28	    message?: string;
29	  };
30	  record?: {
31	    pid: number;
32	    schemaPath: string;
33	    schemaDirectory: string;
34	    schemaText: string;
35	    schema: unknown;
36	    argv: string[];
37	  };
38	  schemaPresentAtAbort?: boolean;
39	  schemaDirectoryExistsAfter?: boolean;
40	  workSettled: boolean;
41	  childAliveAfter?: boolean;
42	  publicationWindow?: {
43	    finalMarkerExists: boolean;
44	    observerWaiting: boolean;
45	    workSettled: boolean;
46	    pendingFile: string;
47	    pendingRecord: State['record'];
48	    pendingFileExistsAfter: boolean;
49	  };
50	  observationError?: { name: string; message: string; code?: string };
51	}
52	
53	afterEach(async () => {
54	  for (const root of roots.splice(0)) {
55	    expect(relative(resolve(tmpdir()), root)).not.toMatch(/^\.\./);
56	    expect(basename(root)).toMatch(/^gg-sdk-schema-/);
57	    await rm(root, { recursive: true, force: true, maxRetries: 5, retryDelay: 50 });
58	  }
59	});
60	
61	async function fixture(
62	  mode: Mode,
63	  length?: number,
64	  controls: { publicationBarrier?: boolean; observerFault?: 'read' | 'parse' } = {},
65	) {
66	  const root = await mkdtemp(join(tmpdir(), 'gg-sdk-schema-'));
67	  roots.push(root);
68	  let temp = join(root, 'temp');
69	  if (length !== undefined) {
70	    while (temp.length + 42 < length) temp = join(temp, 'segment'.repeat(5));
71	    temp = join(temp, 'x'.repeat(length - temp.length - 1));
72	    expect(temp).toHaveLength(length);
73	  }
74	  const home = join(root, 'home');
75	  await Promise.all([mkdir(temp, { recursive: true }), mkdir(home)]);
76	  const unrelated = [join(temp, 'gg-schema-KEEP00'), join(temp, 'gg-structured-keep')];
77	  for (const directory of unrelated) {
78	    await mkdir(directory);
79	    await writeFile(join(directory, 'keep'), mode);
80	  }
81	  await writeFile(join(temp, 'unrelated.txt'), 'Keep this file');
82	  const stateFile = join(root, 'state.json');
83	  const configFile = join(root, 'case.json');
84	  await writeFile(
85	    configFile,
86	    JSON.stringify({
87	      mode,
88	      workingDirectory: root,
89	      schema,
90	      recordFile: join(root, 'schema-record.json'),
91	      stateFile,
92	      ...controls,
93	    }),
94	  );
95	  const env = Object.fromEntries(
96	    Object.entries(process.env).filter(
97	      (entry): entry is [string, string] =>
98	        entry[1] !== undefined &&
99	        /^(PATH|PATHEXT|SYSTEMROOT|WINDIR|COMSPEC|NUMBER_OF_PROCESSORS|PROCESSOR_ARCHITECTURE)$/i.test(
100	          entry[0],
101	        ),
102	    ),
103	  );
104	  const parentTemp = { TEMP: process.env['TEMP'], TMP: process.env['TMP'] };
105	  const execution = execute(process.execPath, [runCase, configFile], {
106	    cwd: root,
107	    env: {
108	      ...env,
109	      TEMP: temp,
110	      TMP: temp,
111	      TMPDIR: temp,
112	      CODEX_HOME: home,
113	      HOME: home,
114	      USERPROFILE: home,
115	      APPDATA: home,
116	      LOCALAPPDATA: home,
117	    },
118	    windowsHide: true,
119	    timeout: 6000,
120	  });
121	  let failure: unknown;
122	  if (controls.observerFault) {
123	    try {
124	      await execution;
125	    } catch (error: unknown) {
126	      failure = error;
127	    }
128	    expect(failure).toMatchObject({ code: 1 });
129	  } else {
130	    const output = await execution;
131	    expect(output.stderr).toBe('');
132	  }
133	  expect({ TEMP: process.env['TEMP'], TMP: process.env['TMP'] }).toEqual(parentTemp);
134	  const state = JSON.parse(await readFile(stateFile, 'utf8')) as State;
135	  if (controls.observerFault) {
136	    expect(state.observationError).toBeDefined();
137	    expect(failure).toMatchObject({
138	      stderr: expect.stringContaining(state.observationError?.message ?? 'Missing observer fault'),
139	    });
140	  }
141	  expect(state.actualTemp).toBe(temp);
142	  for (const directory of unrelated)
143	    expect(await readFile(join(directory, 'keep'), 'utf8')).toBe(mode);
144	  expect(await readFile(join(temp, 'unrelated.txt'), 'utf8')).toBe('Keep this file');
145	  return { temp, state };
146	}
147	
148	it.each(['short', '226-character'].flatMap((label) => modes.map((mode) => ({ label, mode }))))(
149	  '$label root $mode preserves the SDK schema contract and removes only its directory',
150	  async ({ label, mode }) => {
151	    const { temp, state } = await fixture(mode, label === 'short' ? undefined : 226);
152	    if (mode === 'success') {
153	      expect(state.outcome).toEqual({ kind: 'resolved', finalResponse: '{"ok":true}' });
154	    } else {
155	      expect(state.outcome.kind).toBe('rejected');
156	      if (mode === 'error')
157	        expect(state.outcome.message).toContain('Controlled schema fixture failure');
158	      else {
159	        expect(state.outcome.name).toBe('AbortError');
160	        expect(state.schemaPresentAtAbort).toBe(true);
161	      }
162	    }
163	    const record = state.record;
164	    expect(record, 'the real SDK must pass a readable schema to the harmless CLI').toBeDefined();
165	    if (!record) throw new Error('Expected the schema-reading CLI record');
166	    expect(record.argv).toContain('--output-schema');
167	    expect(record.schema).toEqual(schema);
168	    expect(record.schemaText).toBe(JSON.stringify(schema));
169	    expect(dirname(record.schemaDirectory)).toBe(temp);
170	    expect(basename(record.schemaDirectory)).toMatch(/^gg-schema-[A-Za-z0-9]{6}$/);
171	    expect(record.schemaPath).toBe(join(record.schemaDirectory, 'schema.json'));
172	    if (label === '226-character') {
173	      expect(record.schemaDirectory).toHaveLength(243);
174	      expect(record.schemaPath).toHaveLength(255);
175	    }
176	    expect(state.schemaDirectoryExistsAfter).toBe(false);
177	    expect(state.workSettled).toBe(true);
178	    expect(state.childAliveAfter).toBe(false);
